\set ON_ERROR_STOP on
begin;
select no_plan();
-- Independent from earlier transaction/race fixtures; all extra rows roll back.
select synthetic_seed_item(n) from generate_series(41,44) n;
update inventory_items set public_no='QUEUE-'||right(id::text,2),storage_capacity='256 GB',color='Synthetic silver' where id in(select synthetic_item_id(n) from generate_series(41,44)n);
update inventory_product_variants set ram_capacity='8 GB' where id=('70000000-0000-4000-8000-000000000044')::uuid;
select is(synthetic_sales_call(42)->>'status','awaiting_payment','list fixture partial');
select is(synthetic_sales_call(43,'sale.create',10000)->>'status','paid_pending_pickup','list fixture full held');
select is(synthetic_sales_call(44,'sale.create',10000,true)->>'status','delivered','list fixture delivered');
update inventory_items set status='intake',imei_check_status='unchecked',activation_lock_status='unchecked',data_wipe_status='unchecked',functional_grade='untested',cosmetic_grade='unknown' where id=synthetic_item_id(41);
insert into inventory_items select (jsonb_populate_record(null::inventory_items,to_jsonb(i)||jsonb_build_object('id',synthetic_item_id(45),'public_no','QUEUE-45','legacy_payload','{}'::jsonb,'serial_or_imei',null))).* from inventory_items i where id=synthetic_item_id(41);
insert into inventory_items select (jsonb_populate_record(null::inventory_items,to_jsonb(i)||jsonb_build_object('id',synthetic_item_id(46),'public_no','QUEUE-46','legacy_payload','{}'::jsonb,'status','sold'))).* from inventory_items i where id=synthetic_item_id(41);
insert into inventory_items select (jsonb_populate_record(null::inventory_items,to_jsonb(i)||jsonb_build_object('id',synthetic_item_id(47),'public_no','QUEUE-47','store_id','10000000-0000-4000-8000-000000000002','legacy_payload','{}'::jsonb))).* from inventory_items i where id=synthetic_item_id(41);
create temporary table sales_read_results(name text primary key,data jsonb);
insert into sales_read_results values('all',repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','{"queue":"all","search":"QUEUE-","limit":100,"offset":0}')->'data');
select is((select data->'counts' from sales_read_results where name='all'),'{"all":6,"available":2,"awaiting_payment":1,"paid_pending_pickup":1,"delivered":1}'::jsonb,'one list counts include available, three sale states, and old sold history in all');
select is((select (data->>'total')::integer from sales_read_results where name='all'),6,'total excludes foreign store and includes old history');
select is((select jsonb_array_length(data->'rows') from sales_read_results where name='all'),6,'one master inventory page without N+1 stitching');
select is((select r->'order' from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(41)::text),'null'::jsonb,'intake has nullable sale projection');
select is((select r->'inspection'->>'functional_grade' from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(41)::text),'untested','current inspection values are not implicit pass');
select ok((select r->'inspection_missing' ?& array['functional','identifier_check','activation_lock','data_wipe','cosmetic','ready_for_sale'] from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(41)::text),'all real intake deficiencies visible');
select is((select r->>'inspection_href' from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(41)::text),'/inventory/'||synthetic_item_id(41)::text||'/edit','existing edit route is accurate');
select ok((select r->'stock_unit_id'='null'::jsonb and r->'inspection_missing' ? 'stock_unit_required' from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(45)::text),'old no-unit stays readable and explicitly blocked');
select is((select r->'product'->>'identifier' from sales_read_results,jsonb_array_elements(data->'rows')r where r->>'inventory_item_id'=synthetic_item_id(45)::text),'','no fabricated legacy identifier');
select is(synthetic_sales_call(45)->>'code','stale_version','legacy no-unit cannot form a valid CAS command');
select is((select count(*)::integer from inventory_stock_units where legacy_inventory_item_id=synthetic_item_id(45)),0,'reading and attempted sale never manufacture a unit');
insert into sales_read_results values('partial',repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','{"queue":"awaiting_payment","search":"QUEUE-","limit":1}')->'data');
select is((select (data->>'total')::integer from sales_read_results where name='partial'),1,'queue total before pagination is exact');
select is((select data->'counts' from sales_read_results where name='partial'),(select data->'counts' from sales_read_results where name='all'),'queue selection does not corrupt badge totals');
insert into sales_read_results values('page',repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','{"queue":"all","search":"QUEUE-","limit":2,"offset":4}')->'data');
select is((select jsonb_array_length(data->'rows') from sales_read_results where name='page'),2,'server pagination preserves all inventory');
select is((select (data->>'total')::integer from sales_read_results where name='page'),6,'pagination does not truncate total');
select is(repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000005','{}')->>'code','actor_forbidden','viewer denied in SQL list');
select is(repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','{}')->>'code','actor_forbidden','foreign store denied in SQL list');
select is(repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','{"offset":-1}')->>'code','invalid_request','invalid pagination refused');
insert into sales_read_results values('tech',repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','{"search":"QUEUE-"}')->'data');
select ok((select bool_and(r->'customer'='null'::jsonb) from sales_read_results,jsonb_array_elements(data->'rows')r where name='tech'),'technician cannot recover plain customer summary from list');
select is(repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','detail',(select id from inventory_sale_orders where inventory_item_id=synthetic_item_id(42)))->'data'->'customer','null'::jsonb,'technician detail customer redacted in SQL');
insert into sales_read_results values('receipt',repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','receipt',(select id from inventory_sale_orders where inventory_item_id=synthetic_item_id(44)),'sale')->'data');
select is((select data->'product'->>'storage' from sales_read_results where name='receipt'),'256 GB','receipt includes original storage');
select is((select data->'product'->>'ram' from sales_read_results where name='receipt'),'8 GB','receipt includes original RAM');
select is((select data->>'language' from sales_read_results where name='receipt'),'it','SQL print language defaults to Italian');
update store_settings set inventory_sales_print_language='zh' where store_id='10000000-0000-4000-8000-000000000001';
select is(repairdesk_inventory_sales_read('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','receipt',(select id from inventory_sale_orders where inventory_item_id=synthetic_item_id(44)),'sale')->'data'->>'language','zh','SQL reads store default print language');
select throws_ok($$update inventory_transactions set item_id=synthetic_item_id(41) where item_id=synthetic_item_id(42) and transaction_type='sale_payment'$$,'23514',null,'legacy payment cannot move out of protected aggregate');
select throws_ok($$delete from inventory_stock_movements where stock_unit_id=(select stock_unit_id from inventory_sale_orders where inventory_item_id=synthetic_item_id(44))$$,'23514',null,'delivered stock movement is immutable');
select throws_ok($$update inventory_stock_movements set stock_unit_id=(select id from inventory_stock_units where legacy_inventory_item_id=synthetic_item_id(41)) where stock_unit_id=(select stock_unit_id from inventory_sale_orders where inventory_item_id=synthetic_item_id(44))$$,'23514',null,'delivered movement cannot change item');
select throws_ok($$insert into inventory_sale_orders select (jsonb_populate_record(null::inventory_sale_orders,to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'inventory_item_id',synthetic_item_id(41),'stock_unit_id',(select id from inventory_stock_units where legacy_inventory_item_id=synthetic_item_id(41)),'sale_number','SYNTHETIC-INVALID-DELIVERY','delivered_at',null))).* from inventory_sale_orders o where inventory_item_id=synthetic_item_id(44)$$,'23514',null,'delivered CHECK rejects NULL timestamp independently of RPC');
set local role service_role;
select is((repairdesk_inventory_sales_list('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','{"search":"QUEUE-"}')->'data'->>'total')::integer,6,'enabled service role uses bounded list RPC');
reset role;
select synthetic_seed_item(n) from generate_series(48,51)n;
select is(repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','sale.create',gen_random_uuid(),
  synthetic_sales_payload(48,'sale.create',10000,true)||'{"agreed_at":"2024-03-30T23:00:00Z","payment":{"amount_cents":10000,"method":"cash","occurred_at":"2024-03-31T22:15:00Z"},"delivered_at":"2024-03-31T22:30:00Z"}'::jsonb)->>'code','completed','DST boundary physical delivery accepted');
select is((select starts_on::text from inventory_warranty_versions where sale_order_id=(select id from inventory_sale_orders where inventory_item_id=synthetic_item_id(48))),'2024-04-01','Rome delivery calendar date differs correctly from UTC date');
select is((select ends_on::text from inventory_warranty_versions where sale_order_id=(select id from inventory_sale_orders where inventory_item_id=synthetic_item_id(48))),'2026-04-01','24 calendar months use Rome anniversary');
select is(repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','sale.create',gen_random_uuid(),synthetic_sales_payload(49))->>'code','completed','manager existing sale/payment matrix accepted in DB');
select is(repairdesk_inventory_sales_command('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000003','sale.create',gen_random_uuid(),synthetic_sales_payload(50))->>'code','completed','sales existing sale/payment matrix accepted in DB');
select is(synthetic_sales_call(51)->>'code','completed','atomic append delivery fixture');
select is(synthetic_sales_call(51,'payment.append',7000,true)->>'status','delivered','final collection and delivery happen atomically');
select is((select count(*)::integer from inventory_stock_movements where stock_unit_id=(select stock_unit_id from inventory_sale_orders where inventory_item_id=synthetic_item_id(51))),1,'atomic append produces one delivery movement');
select is((select count(*)::integer from inventory_transactions where item_id=synthetic_item_id(51) and transaction_type='sale_payment'),2,'atomic append preserves both receipt transactions');
select * from finish();
rollback;
